/** Proposed genuine survival/entity/datapack integration tests. No mock players or invented stock. */
public final class EquipmentGameTests {
    private static final String STRUCTURE="create_test:reservoir";
    private static final BlockPos P=new BlockPos(4,4,4);
    static {BacktankUtil.addBacktankSupplier(entity->{var stack=entity.getItemBySlot(EquipmentSlot.CHEST);return stack.has(AllDataComponents.BACKTANK_AIR)?List.of(stack):List.of();});}
    private static NativeSurvivalTestPlayer player(GameTestHelper h){return NativeSurvivalTestPlayer.join(h,Vec3.atBottomCenterOf(h.absolutePos(P)));}
    private static ItemStack named(Item item,int count){var stack=new ItemStack(item,count);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original finite equipment stock"));return stack;}
    private static List<PotatoProjectileEntity> projectiles(GameTestHelper h){return h.getLevel().getEntitiesOfClass(PotatoProjectileEntity.class,new AABB(h.absolutePos(P)).inflate(12));}
    private static PotatoProjectileEntity projectile(GameTestHelper h,Item item){var result=AllEntityTypes.POTATO_PROJECTILE.create(h.getLevel(),EntitySpawnReason.TRIGGERED);h.assertTrue(result!=null,"Actual registered projectile constructs");result.setItem(named(item,1));result.setPos(Vec3.atCenterOf(h.absolutePos(P)));h.assertTrue(h.getLevel().addFreshEntity(result),"Native entity manager admits genuine projectile");return result;}
    private static PotatoProjectileEntity restore(GameTestHelper h,PotatoProjectileEntity original){var output=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,h.getLevel().registryAccess());h.assertTrue(original.saveAsPassenger(output),"Actual entity saves with registered type");var saved=output.buildResult();saved.putDouble("acceleration_power",.1);var result=EntityType.loadEntityRecursive(saved,h.getLevel(),new EntitySpawnRequest(EntitySpawnReason.LOAD,false),EntityProcessor.NOP);h.assertTrue(result instanceof PotatoProjectileEntity,"Native loader restores real create:potato_projectile");var restored=(PotatoProjectileEntity)result;h.assertValueEqual(restored.accelerationPower,.1d,"Actual reload preserves the genuine saved inherited acceleration .1; the separate original3955 import regression retains its exact .125");return restored;}
    @GameTest(structure=STRUCTURE) public void dynamicDatapackContainsEveryOriginalAmmoAndActualCodecRegistries(GameTestHelper h){
        var registry=h.getLevel().registryAccess().lookupOrThrow(CreateRegistries.POTATO_PROJECTILE_TYPE);h.assertValueEqual(registry.size(),25,"All original actual datapack projectile entries loaded");h.assertValueEqual(CreateBuiltInRegistries.POTATO_PROJECTILE_ENTITY_HIT_ACTION.size(),6,"All original entity action codecs registered");h.assertValueEqual(CreateBuiltInRegistries.POTATO_PROJECTILE_BLOCK_HIT_ACTION.size(),2,"Both source block action codecs registered");h.assertValueEqual(CreateBuiltInRegistries.POTATO_PROJECTILE_RENDER_MODE.size(),4,"All source render codecs registered and synchronized");
        var apple=PotatoCannonProjectileType.getTypeForItem(h.getLevel().registryAccess(),Items.ENCHANTED_GOLDEN_APPLE).orElseThrow().value();h.assertTrue(apple.onEntityHit().orElseThrow() instanceof AllPotatoProjectileEntityHitActions.FoodEffects food&&food.effects().size()==4,"Native food migration retains all four original enchanted apple effects");h.succeed();
    }
    @GameTest(structure=STRUCTURE) public void actualPlayerTicksSwitchSingleDualAndEmptyReachWithoutStacking(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();double base=p.getAttributeValue(Attributes.BLOCK_INTERACTION_RANGE);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AllItems.EXTENDO_GRIP));p.doTick();h.assertValueEqual(p.getAttributeValue(Attributes.BLOCK_INTERACTION_RANGE),base+3,"Real player tick installs source single modifier");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.EXTENDO_GRIP));p.doTick();h.assertValueEqual(p.getAttributeValue(Attributes.BLOCK_INTERACTION_RANGE),base+5,"Actual dual modifiers replace the single range");p.doTick();h.assertValueEqual(p.getAttributeValue(Attributes.BLOCK_INTERACTION_RANGE),base+5,"Repeated actual ticks never stack grip range");p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);p.doTick();h.assertValueEqual(p.getAttributeValue(Attributes.BLOCK_INTERACTION_RANGE),base,"Unequipping both removes all source grip range");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void survivalCannonDebitsOneNamedAmmoAndOneRealToolCharge(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var cannon=new ItemStack(AllItems.POTATO_CANNON);var ammo=named(Items.POTATO,7);p.setItemInHand(InteractionHand.MAIN_HAND,cannon);p.getInventory().setItem(9,ammo);h.assertTrue(AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND).consumesAction(),"Actual use fires source cannon");h.assertValueEqual(ammo.getCount(),6,"One original physical potato debited");h.assertValueEqual(cannon.getDamageValue(),1,"Literal survival tool consumes one durability");var entities=projectiles(h);h.assertValueEqual(entities.size(),1,"One real source projectile admitted");var fired=entities.getFirst();h.assertTrue(fired.getOwner()==p&&fired.getItem().getHoverName().equals(ammo.getHoverName()),"Exact actual owner and original components are retained");h.assertTrue(p.getCooldowns().isOnCooldown(cannon),"Actual native stack cooldown is active");ammo.set(DataComponents.CUSTOM_NAME,Component.literal("Inventory changed later"));h.assertTrue(!fired.getItem().getHoverName().equals(ammo.getHoverName()),"Real projectile snapshot is independent of later inventory edits");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void cannonWithoutRecognizedAmmoLeavesFiniteToolAndInventoryUntouched(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var cannon=new ItemStack(AllItems.POTATO_CANNON);p.setItemInHand(InteractionHand.MAIN_HAND,cannon);p.getInventory().setItem(9,named(Items.DIAMOND,7));h.assertFalse(AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND).consumesAction(),"Unrecognized actual item is not ammunition");h.assertTrue(projectiles(h).isEmpty(),"No fabricated projectile without real ammo");h.assertValueEqual(p.getInventory().getItem(9).getCount(),7,"All original diamonds retained");h.assertValueEqual(cannon.getDamageValue(),0,"Dry fire has no source tool cost");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void splitShotHasThreeRealProjectilesButOneAmmoChargeAndOneRecoveryCandidate(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var cannon=new ItemStack(AllItems.POTATO_CANNON);cannon.enchant(p.registryAccess().lookupOrThrow(Registries.ENCHANTMENT).getOrThrow(AllEnchantments.POTATO_RECOVERY),3);var ammo=named(Items.SWEET_BERRIES,7);p.setItemInHand(InteractionHand.MAIN_HAND,cannon);p.getInventory().setItem(9,ammo);AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND);var shots=projectiles(h);h.assertValueEqual(shots.size(),3,"Original berry split spawns three physical projectiles");h.assertValueEqual(ammo.getCount(),6,"One actual berry pays for original split");h.assertValueEqual(cannon.getDamageValue(),1,"One actual charge pays for source spray");h.assertValueEqual(shots.stream().filter(shot->shot.recoveryChance==.5f).count(),1L,"Only original first projectile carries actual RecoveryIII");h.assertValueEqual(shots.stream().filter(shot->shot.recoveryChance==0).count(),2L,"Extra source pellets cannot duplicate recoverable ammo");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void dualCannonsAlternateTheirActualHandsAndUseTwoThirdsCooldown(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var main=new ItemStack(AllItems.POTATO_CANNON);var off=new ItemStack(AllItems.POTATO_CANNON);var ammo=named(Items.POTATO,7);p.setItemInHand(InteractionHand.MAIN_HAND,main);p.setItemInHand(InteractionHand.OFF_HAND,off);p.getInventory().setItem(9,ammo);AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND);h.assertTrue(main.has(AllDataComponents.SHAPER_SWAP),"First genuine use arms the original offhand handoff");h.assertValueEqual(p.getCooldowns().getCooldownPercent(main,0),1f,"Actual cooldown starts full");for(int i=0;i<10;i++)p.getCooldowns().tick();h.assertFalse(p.getCooldowns().isOnCooldown(main),"Source potato15 tick reload becomes actual10 tick dual cooldown");h.assertFalse(AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND).consumesAction(),"Alternating main hand passes through after actual cooldown");h.assertTrue(AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.OFF_HAND).consumesAction(),"Actual offhand then fires");h.assertValueEqual(main.getDamageValue(),1,"First cannon paid only its actual shot");h.assertValueEqual(off.getDamageValue(),1,"Second cannon paid its actual shot");h.assertValueEqual(ammo.getCount(),5,"Exactly two finite original rounds spent");h.assertFalse(main.has(AllDataComponents.SHAPER_SWAP),"Source handoff marker clears on actual offhand use");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualAddonSupplierAirPaysSourceShotAndThenFiniteDurabilityTakesOver(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var supplied=named(Items.IRON_CHESTPLATE,1);supplied.set(AllDataComponents.BACKTANK_AIR,4);p.setItemSlot(EquipmentSlot.CHEST,supplied);var cannon=new ItemStack(AllItems.POTATO_CANNON);p.setItemInHand(InteractionHand.MAIN_HAND,cannon);p.getInventory().setItem(9,named(Items.POTATO,7));AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND);h.assertValueEqual(supplied.get(AllDataComponents.BACKTANK_AIR),0,"Actual addon-supplied equipped stack spends source floor900/200=4 air");h.assertValueEqual(cannon.getDamageValue(),0,"Real source air paid first shot instead of durability");for(int i=0;i<15;i++)p.getCooldowns().tick();AllItems.POTATO_CANNON.use(h.getLevel(),p,InteractionHand.MAIN_HAND);h.assertValueEqual(cannon.getDamageValue(),1,"After actual air depletion source durability pays the next shot");h.assertValueEqual(p.getInventory().getItem(9).getCount(),5,"Air never manufactures ammo");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void extendoPlacementAndBreakingChargeActualOffhandOncePerSuccessfulWorldAction(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var grip=new ItemStack(AllItems.EXTENDO_GRIP);p.setItemInHand(InteractionHand.OFF_HAND,grip);ExtendoGripItem.holdingExtendoGripIncreasesRange(p);var support=P.east(2).below();h.setBlock(support,Blocks.STONE);p.setItemInHand(InteractionHand.MAIN_HAND,named(Items.COBBLESTONE,7));var pos=h.absolutePos(support);var hit=new BlockHitResult(Vec3.atCenterOf(pos).add(0,.5,0),Direction.UP,pos,false);h.assertTrue(Items.COBBLESTONE.useOn(new UseOnContext(p,InteractionHand.MAIN_HAND,hit)).consumesAction(),"Actual vanilla block item placement succeeds");h.assertBlockPresent(Blocks.COBBLESTONE,support.above());h.assertValueEqual(grip.getDamageValue(),1,"One real placement charges actual offhand grip once");h.assertTrue(p.gameMode.destroyBlock(h.absolutePos(support.above())),"Actual native server block break succeeds");h.assertValueEqual(grip.getDamageValue(),2,"One real break charges actual offhand grip once");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void extendoRealAttackConsumesOneChargeAndNativeDamageSourceAddsKnockback(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var grip=new ItemStack(AllItems.EXTENDO_GRIP);p.setItemInHand(InteractionHand.OFF_HAND,grip);var pig=h.spawn(EntityTypes.PIG,P.east(2));pig.setNoAi(true);pig.setDeltaMovement(Vec3.ZERO);p.attack(pig);h.assertTrue(pig.getHealth()<pig.getMaxHealth(),"Real native pig takes actual player attack damage");h.assertValueEqual(grip.getDamageValue(),1,"Actual source-owned incoming attack charges one grip action");h.assertTrue(pig.getDeltaMovement().horizontalDistance()>.5,"Native knockback receives actual direct Player source and source+2 strength");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualCrouchedGripAndEmptyHandOpenNativeChestWithoutInventingAnItemUse(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var target=P.east(2);h.setBlock(target,Blocks.CHEST);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AllItems.EXTENDO_GRIP));p.setShiftKeyDown(true);ExtendoGripItem.holdingExtendoGripIncreasesRange(p);var absolute=h.absolutePos(target);var hit=new BlockHitResult(Vec3.atCenterOf(absolute).add(-.499,0,0),Direction.WEST,absolute,false);var result=p.gameMode.useItemOn(p,h.getLevel(),p.getMainHandItem(),InteractionHand.MAIN_HAND,hit);h.assertTrue(result.consumesAction()&&p.containerMenu!=p.inventoryMenu,"Actual native block input honors original grip sneak-bypass and opens the real chest menu");h.assertValueEqual(p.getOffhandItem().getDamageValue(),0,"Opening actual chest is not a source break/place/damage action");p.closeContainer();}h.succeed();}
    @GameTest(structure=STRUCTURE) public void extendoPacketRejectsOldHoldingAndOutOfRangeTargetsWithoutDamage(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();var pig=h.spawn(EntityTypes.PIG,P.east(8));pig.setNoAi(true);p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AllItems.EXTENDO_GRIP));ExtendoGripItem.holdingExtendoGripIncreasesRange(p);h.assertFalse(new ExtendoGripInteractionPacket(pig).handle(p),"Single source grip cannot reach original target eight blocks away");p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(AllItems.EXTENDO_GRIP));h.assertTrue(new ExtendoGripInteractionPacket(pig).handle(p),"Actual dual source grips reach the genuine same target");float health=pig.getHealth();p.setItemInHand(InteractionHand.MAIN_HAND,ItemStack.EMPTY);p.setItemInHand(InteractionHand.OFF_HAND,ItemStack.EMPTY);h.assertFalse(new ExtendoGripInteractionPacket(pig).handle(p),"Stale packet cannot retain held-grip capability");h.assertValueEqual(pig.getHealth(),health,"Rejected stale owner action causes no second damage");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void extendoPacketRejectsNonfiniteSpecificHitPointsAndOccludedLongReach(GameTestHelper h){try(var fixture=player(h)){var p=fixture.player();p.setItemInHand(InteractionHand.OFF_HAND,new ItemStack(AllItems.EXTENDO_GRIP));var pig=h.spawn(EntityTypes.PIG,P.east(5));pig.setNoAi(true);ExtendoGripItem.holdingExtendoGripIncreasesRange(p);h.assertFalse(new ExtendoGripInteractionPacket(pig,InteractionHand.MAIN_HAND,new Vec3(Double.NaN,0,0)).handle(p),"Native specific interaction rejects nonfinite hit point");h.assertFalse(new ExtendoGripInteractionPacket(pig,InteractionHand.MAIN_HAND,new Vec3(100,0,0)).handle(p),"Native specific interaction stays inside actual target bounds");for(int y=0;y<4;y++)for(int z=-1;z<=1;z++)h.setBlock(P.east(2).offset(0,y,z),Blocks.STONE);h.assertFalse(p.hasLineOfSight(pig),"Actual world wall occludes original target");h.assertFalse(new ExtendoGripInteractionPacket(pig).handle(p),"Source occlusion subtracts three real blocks from grip reach");h.assertValueEqual(pig.getHealth(),pig.getMaxHealth(),"All invalid actual actions leave target undamaged");}h.succeed();}
    @GameTest(structure=STRUCTURE) public void originalProjectileHitsNativePigAndRetainsSourceBallisticDamage(GameTestHelper h){var pig=h.spawn(EntityTypes.PIG,P.east(2));pig.setNoAi(true);var shot=projectile(h,Items.POTATO);shot.setDeltaMovement(new Vec3(1,0,0));float health=pig.getHealth();shot.onHitEntity(new EntityHitResult(pig,pig.position()));h.assertValueEqual(pig.getHealth(),health-5,"Real registered potato data applies source five damage");h.assertTrue(shot.isRemoved(),"Nonsticky source projectile is actually removed on native hit");h.assertTrue(pig.getDeltaMovement().horizontalDistance()>0,"Source potato knockback changes actual native pig movement");h.succeed();}
    // Historical method/native ID is retained; pinned1.21.1 already applies inherited normalized thrust .1.
    @GameTest(structure=STRUCTURE) public void nativeProjectileTickUsesSourceGravityDragAndZeroInheritedAcceleration(GameTestHelper h){var shot=projectile(h,Items.POTATO);shot.setDeltaMovement(1,0,0);var before=shot.position();shot.tick();h.assertValueEqual(shot.accelerationPower,.1d,"Pinned1.21.1 and native26.3 both retain inherited default acceleration .1");var sourceGravityDrag=new Vec3(.99,-.0495,0);var expectedVelocity=sourceGravityDrag.add(sourceGravityDrag.normalize().scale(.1));h.assertTrue(shot.getDeltaMovement().distanceToSqr(expectedVelocity)<1e-12,"Actual native tick applies source gravity.05/drag.99, then the pinned vanilla normalized movement thrust .1");h.assertTrue(shot.position().x>before.x&&shot.position().y<before.y,"Actual native world movement follows source ballistics");h.assertTrue(shot.isPickable()&&shot.canBeHitByProjectile(),"Native26.3 inherited pickability migration preserves source projectile collisions");h.succeed();}
    @GameTest(structure=STRUCTURE) public void potatoAndCarrotActuallyPlantOnFarmlandAndRejectSolidConfiguredBlocks(GameTestHelper h){var soil=P.east(2);h.setBlock(soil,Blocks.FARMLAND);var absolute=h.absolutePos(soil);var hit=new BlockHitResult(Vec3.atCenterOf(absolute).add(0,.5,0),Direction.UP,absolute,false);var potato=projectile(h,Items.POTATO);potato.onHitBlock(hit);h.assertBlockPresent(Blocks.POTATOES,soil.above());h.setBlock(soil.above(),Blocks.AIR);var carrot=projectile(h,Items.CARROT);carrot.onHitBlock(hit);h.assertBlockPresent(Blocks.CARROTS,soil.above());h.setBlock(soil.above(),Blocks.AIR);h.assertFalse(new AllPotatoProjectileBlockHitActions.PlantCrop(Blocks.DIAMOND_BLOCK).execute(h.getLevel(),new ItemStack(Items.CARROT),hit),"A configured solid block never becomes a false source plantable");h.assertBlockPresent(Blocks.AIR,soil.above());h.succeed();}
    @GameTest(structure=STRUCTURE) public void melonBlockHitPlacesActualVanillaBlockAndSideHitCreatesGenuineFallingBlock(GameTestHelper h){var support=P.east(2);h.setBlock(support,Blocks.STONE);var absolute=h.absolutePos(support);projectile(h,Items.MELON).onHitBlock(new BlockHitResult(Vec3.atCenterOf(absolute).add(0,.5,0),Direction.UP,absolute,false));h.assertBlockPresent(Blocks.MELON,support.above());var side=projectile(h,Items.PUMPKIN);side.onHitBlock(new BlockHitResult(Vec3.atCenterOf(absolute).add(.5,0,0),Direction.EAST,absolute,false));h.assertValueEqual(h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(absolute).inflate(2)).size(),1,"Original side action admits one real native falling block");h.succeed();}
    @GameTest(structure=STRUCTURE) public void enchantedAppleProjectileRetainsAllOriginalFoodEffectsAfterNativeConsumableMigration(GameTestHelper h){var pig=h.spawn(EntityTypes.PIG,P.east(2));pig.setNoAi(true);var shot=projectile(h,Items.ENCHANTED_GOLDEN_APPLE);shot.onHitEntity(new EntityHitResult(pig,pig.position()));for(var effect:List.of(MobEffects.REGENERATION,MobEffects.RESISTANCE,MobEffects.FIRE_RESISTANCE,MobEffects.ABSORPTION))h.assertTrue(pig.hasEffect(effect),"Original source enchanted-apple effect applied to genuine native target: "+effect);h.assertTrue(shot.isRemoved(),"Actual nonsticky effect projectile is consumed");h.succeed();}
    @GameTest(structure=STRUCTURE) public void sourceGoldenAppleUsesRealVanillaZombieConversion(GameTestHelper h){var zombie=h.spawn(EntityTypes.ZOMBIE_VILLAGER,P.east(2));zombie.setNoAi(true);zombie.addEffect(new MobEffectInstance(MobEffects.WEAKNESS,600));projectile(h,Items.GOLDEN_APPLE).onHitEntity(new EntityHitResult(zombie,zombie.position()));h.assertTrue(zombie.isConverting(),"Original named Converter helper invokes actual native zombie-villager conversion");var pig=h.spawn(EntityTypes.PIG,P.west(2));pig.setNoAi(true);projectile(h,Items.GOLDEN_APPLE).onHitEntity(new EntityHitResult(pig,pig.position()));for(var effect:List.of(MobEffects.REGENERATION,MobEffects.ABSORPTION))h.assertTrue(pig.hasEffect(effect),"Lazy native golden-apple fallback retains actual source effect: "+effect);h.succeed();}
    @GameTest(structure=STRUCTURE) public void stickyProjectileSaveLoadRestoresActualTargetUuidOffsetAndNamedAmmo(GameTestHelper h){var pig=h.spawn(EntityTypes.PIG,P.east(2));pig.setNoAi(true);var shot=projectile(h,Items.CAKE);shot.setPos(pig.position().add(.2,.8,0));shot.onHitEntity(new EntityHitResult(pig,shot.position()));h.assertTrue(shot.isAlive()&&shot.getStuckEntity()==pig,"Sticky original cake remains attached to actual native target");var restored=restore(h,shot);h.assertTrue(restored.getStuckEntity()==pig,"Actual entity UUID resolves the original live target after native load");h.assertValueEqual(restored.stuckOffset,shot.stuckOffset,"Actual source attachment offset persists");h.assertTrue(ItemStack.matches(restored.getItem(),shot.getItem()),"Native save retains original named ammo components");h.assertValueEqual(restored.getProjectileType(),shot.getProjectileType(),"Source dynamic registry type survives actual native save/load");h.succeed();}
    @GameTest(structure=STRUCTURE) public void actualCannonEnchantmentSetterPreservesPinnedRecoveryOnlyBehaviorAndNativePersistence(GameTestHelper h){var shot=projectile(h,Items.POTATO);var cannon=new ItemStack(AllItems.POTATO_CANNON);var lookup=h.getLevel().registryAccess().lookupOrThrow(Registries.ENCHANTMENT);cannon.enchant(lookup.getOrThrow(AllEnchantments.POTATO_RECOVERY),3);cannon.enchant(lookup.getOrThrow(Enchantments.POWER),5);cannon.enchant(lookup.getOrThrow(Enchantments.PUNCH),2);shot.setEnchantmentEffectsFromCannon(cannon);h.assertValueEqual(shot.recoveryChance,.5f,"Source RecoveryIII grants actual50% recovery");h.assertValueEqual(shot.additionalDamageMult,1f,"Pinned source setter never applies Power to actual projectile damage");h.assertValueEqual(shot.additionalKnockback,0f,"Pinned source setter never applies Punch to actual projectile knockback");var restored=restore(h,shot);h.assertValueEqual(restored.recoveryChance,.5f,"Recovery data persists through genuine native save/load");h.succeed();}
}
